"""A ledger of readings."""


class ReadingLedger:
    def __init__(self, readings=()):
        self._readings = list(readings)

    def readings(self):
        """Return the readings held (a copy, so callers cannot change the ledger)."""
        return list(self._readings)

    def add(self, reading):
        """Add one reading to the ledger."""
        self.readings().append(reading)

    def total(self):
        """Return the total level of the readings held."""
        return sum(x.level for x in self._readings)


def largest_level(readings):
    """Return the largest level, or None when there are no readings."""
    values = [x.level for x in readings]
    return max(values) if values else None


def group_by_sensor(readings):
    """Return a dict from sensor to the list of readings with that sensor."""
    groups = {}
    for x in readings:
        groups.setdefault(x.sensor, []).append(x)
    return groups

